import{_ as n,C as i,o as t,c as s,a2 as r,b as d,w as o,a as c,E as l,a3 as u}from"./chunks/framework.XaTYfhfj.js";const _=JSON.parse('{"title":"14.2 Architecture Styles & Federation Topology","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/14.2-architecture-styles.md","filePath":"system-design/14.2-architecture-styles.md"}'),h={name:"system-design/14.2-architecture-styles.md"};function g(p,e,m,A,b,f){const a=i("Mermaid");return t(),s("div",null,[e[1]||(e[1]=r('<h1 id="_14-2-architecture-styles-federation-topology" tabindex="-1">14.2 Architecture Styles &amp; Federation Topology <a class="header-anchor" href="#_14-2-architecture-styles-federation-topology" aria-label="Permalink to &quot;14.2 Architecture Styles &amp; Federation Topology&quot;">​</a></h1><h2 id="_1-what-it-is-in-plain-words" tabindex="-1">1. What It Is in Plain Words <a class="header-anchor" href="#_1-what-it-is-in-plain-words" aria-label="Permalink to &quot;1. What It Is in Plain Words&quot;">​</a></h2><p>An architecture style is the foundational pattern used to organize an application&#39;s code, runtime boundaries, and communication paths. It dictates whether code runs as a single unified process (monolith), distributed microservices, ephemeral cloud functions (serverless), or decentralized frontend applications (micro-frontends).</p><hr><h2 id="_2-truthguard-architectural-paradigm" tabindex="-1">2. TruthGuard Architectural Paradigm <a class="header-anchor" href="#_2-truthguard-architectural-paradigm" aria-label="Permalink to &quot;2. TruthGuard Architectural Paradigm&quot;">​</a></h2><p>TruthGuard utilizes a <strong>Federated Micro-Frontend Architecture</strong> coupled with <strong>Serverless Edge Function Gateways</strong>. Rather than building a monolithic web application, each specialized forensic modality (TruthLence, DEEP SCAN Camera, DeepGuard Telecom, MediaVault) runs as an autonomous Vite single-page application coordinated by the central Hub (<code>mainpage</code>).</p>',6)),(t(),d(u,null,{default:o(()=>[l(a,{id:"mermaid-16",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20subgraph%20FederatedHub%20%5B%22Federated%20Micro-Frontend%20Hub%20(Port%205173)%22%5D%0A%20%20%20%20%20%20%20%20HubCore%5BHub.tsx%5D%0A%20%20%20%20%20%20%20%20Prober%5BFeatureEmbed.tsx%3A%20Dynamic%20Port%20Scanner%5D%0A%20%20%20%20%20%20%20%20VeritAI%5BVeritAIApp.tsx%3A%20Executive%20Workstation%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20AutonomousEngines%20%5B%22Decentralized%20Forensic%20Subsystems%22%5D%0A%20%20%20%20%20%20%20%20E1%5B%22TruthLence%20Engine%20(Port%205176)%22%5D%0A%20%20%20%20%20%20%20%20E2%5B%22DEEP%20SCAN%20Camera%20Engine%20(Port%205183)%22%5D%0A%20%20%20%20%20%20%20%20E3%5B%22DeepGuard%20Telecom%20Engine%20(Port%205182)%22%5D%0A%20%20%20%20%20%20%20%20E4%5B%22MediaVault%20Drive%20Engine%20(Port%205184)%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20EdgeGateways%20%5B%22Serverless%20Edge%20Tier%22%5D%0A%20%20%20%20%20%20%20%20Edge1%5B%22analyze-media%20Deno%20Function%22%5D%0A%20%20%20%20%20%20%20%20Edge2%5B%22analyze-content%20Deno%20Function%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20HubCore%20--%3E%20AutonomousEngines%0A%20%20%20%20Prober%20%3D%3D%3E%7CNon-blocking%20HEAD%20Port%20Scan%7C%20AutonomousEngines%0A%20%20%20%20E1%20--%3E%20Edge1%0A%20%20%20%20E3%20--%3E%20Edge2%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<hr><h2 id="_3-comparison-across-architecture-styles" tabindex="-1">3. Comparison Across Architecture Styles <a class="header-anchor" href="#_3-comparison-across-architecture-styles" aria-label="Permalink to &quot;3. Comparison Across Architecture Styles&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Architecture Style</th><th>Coupling Level</th><th>Build Complexity</th><th>Failure Isolation</th><th>Scalability</th><th>Local Dev Ergonomics</th><th>Fit with TruthGuard</th></tr></thead><tbody><tr><td><strong>Federated Micro-Frontends (Chosen)</strong></td><td><strong>Loose</strong></td><td><strong>Low</strong></td><td><strong>Complete</strong></td><td><strong>Independent per tool</strong></td><td><strong>High (Port-based)</strong></td><td><strong>Optimal</strong></td></tr><tr><td><strong>Monolithic Single-Page App</strong></td><td>Tight</td><td>Low</td><td>Zero (One error crashes app)</td><td>Unified only</td><td>Fast start</td><td>Poor (Bundle bloat)</td></tr><tr><td><strong>Single-SPA Monorepo</strong></td><td>Moderate</td><td>High</td><td>Moderate (Shared window)</td><td>High</td><td>Complex</td><td>Moderate</td></tr><tr><td><strong>Microservices Backend (Node/Docker)</strong></td><td>Loose</td><td>High</td><td>High</td><td>Independent per service</td><td>Heavy (Many containers)</td><td>Overkill for client forensics</td></tr><tr><td><strong>Serverless Monolith (Next.js SSR)</strong></td><td>Moderate</td><td>Moderate</td><td>High</td><td>Automatic</td><td>Moderate</td><td>Poor (Cold starts)</td></tr></tbody></table><hr><h2 id="_4-trade-offs-accepted" tabindex="-1">4. Trade-Offs Accepted <a class="header-anchor" href="#_4-trade-offs-accepted" aria-label="Permalink to &quot;4. Trade-Offs Accepted&quot;">​</a></h2><ul><li><strong>Benefit: Complete Fault Isolation</strong>: If an investigator uploads an abnormal file that crashes the DEEP SCAN camera parser, the Hub and MediaVault continue operating without disruption.</li><li><strong>Benefit: Independent Tech Stacks</strong>: MediaVault can use Zustand for state management while VeritAI uses React Context, without dependency collisions.</li><li><strong>Trade-Off: Duplicate Browser Heap</strong>: Running multiple micro-frontends simultaneously consumes more RAM than a single shared bundle.</li><li><strong>Trade-Off: Cross-Application State</strong>: State sharing must rely on browser storage (<code>localStorage</code>) or query parameters rather than in-memory pointers.</li></ul><hr><h2 id="_5-how-a-senior-engineer-would-improve-it-for-enterprise" tabindex="-1">5. How a Senior Engineer Would Improve It for Enterprise <a class="header-anchor" href="#_5-how-a-senior-engineer-would-improve-it-for-enterprise" aria-label="Permalink to &quot;5. How a Senior Engineer Would Improve It for Enterprise&quot;">​</a></h2><ol><li><strong>Unified Reverse Proxy Routing</strong>: Replace local port scanning with an NGINX or Envoy reverse proxy routing path-based subdomains (<code>/truthlence</code>, <code>/camera</code>, <code>/vault</code>).</li><li><strong>Shared Component Design Tokens</strong>: Publish the NVIDIA design system as a versioned npm package (<code>@truthguard/design-system</code>) to guarantee 100% token synchronization.</li><li><strong>Web Worker Threading</strong>: Move CPU-heavy binary parsing off the main thread into dedicated background workers.</li></ol><hr><h2 id="_6-30-second-spoken-interview-answer" tabindex="-1">6. 30-Second Spoken Interview Answer <a class="header-anchor" href="#_6-30-second-spoken-interview-answer" aria-label="Permalink to &quot;6. 30-Second Spoken Interview Answer&quot;">​</a></h2><blockquote><p>&quot;I chose a federated micro-frontend architecture backed by serverless Edge Functions over a traditional monolithic React app. In a digital forensics suite, modularity and failure isolation are critical: if the camera tamper analyzer crashes on a corrupted EXIF header, the investigator&#39;s active evidence custody drive in MediaVault must not be terminated.</p><p>Our central Hub coordinates independent engines using a client-side port prober, allowing each tool to be built, tested, and scaled autonomously.&quot;</p></blockquote>',12))])}const E=n(h,[["render",g]]);export{_ as __pageData,E as default};
